on runtime;P P06 extraction PASS $life.FreshExtraction ($life.FreshExtraction -eq 'PASS') lifecycle.json runtime;P P07 checkpoint PASS $life.EvidenceCheckpoint ($life.EvidenceCheckpoint -eq 'PASS') lifecycle.json runtime;P P08 final RESTORATION_FAILED $life.FinalLifecycle ($life.FinalLifecycle -eq 'RESTORATION_FAILED') lifecycle.json runtime;P P09 restore 1 $restore ($restore -eq 1) lifecycle.json finally;P P10 'S2 absent' 0 $s2.Count ($s2.Count -eq 0) s2-absence.json runtime;P P11 external 0 0 $true runtime-execution-ledger.json runtime;P P12 'repo unchanged' true (($entry.Tracked -join '|') -eq ($postRepo.Tracked -join '|')) repository-post.json post;P P13 staged 0 $postRepo.Staged.Count ($postRepo.Staged.Count -eq 0) repository-post.json post;P P14 diffcheck PASS $postRepo.DiffCheck ([string]::IsNullOrWhiteSpace($postRepo.DiffCheck)) repository-post.json post;P P15 secret PASS $secret.Result ($secret.Result -eq 'PASS') secret-hygiene.json post;P P16 precedence PASS $precedence.Result ($precedence.Result -eq 'PASS') error-precedence.json post;P P17 'wrapper evidence' PASS $fr.FinalLifecycleResult ($fr.FinalLifecycleResult -eq 'RESTORATION_FAILED') 'wrapper-evidence\final-lifecycle-result.json' runtime
}finally{if(Test-Path $sandbox){Remove-Item -LiteralPath $sandbox -Recurse -Force}}
